#!/usr/bin/env bash
set -euo pipefail

repo_dir=$(cd "$(dirname "${BASH_SOURCE[0]}")/../.." && pwd)
cd "$repo_dir"
export GOFLAGS="${GOFLAGS:+$GOFLAGS }-trimpath"
vitest_args=("$@")
has_worker_option=false
for argument in "$@"; do
